---@class SShopMgr
local SShopMgr = T(Global, "SShopMgr")
---@type SShop
local Shop = Plugins.Require("shop", "server.data.SShop")
---@type PidPacketSender : SPidPacketSender
local PidPacketSender = T(Global, "PidPacketSender")
---@type PathUtil
local PathUtil = T(Global, "PathUtil")
-- 引入lfs模块用于文件系统操作
local lfs = require("lfs")
---@type [string, SShop]
local Shops = {}
local index = 1

-- 商店数据文件路径
local SHOP_DATA_PATH = "plugins/shop/shops.json"

-- 保存商店数据到JSON文件
function SShopMgr:saveShopsToFile()
    local shopData = {
        shops = {},
        index = index
    }
    
    -- 收集所有商店的保存信息
    for id, shop in pairs(Shops) do
        shopData.shops[id] = shop:getSaveInfo()
    end
    
    -- 构建完整的文件路径
    local fullPath = FileUtil:getMapPath() .. SHOP_DATA_PATH
    
    -- 检测并创建目录
    local dirPath = FileUtil:getMapPath() .. "plugins/shop/"
    
    -- 检查目录是否存在，不存在则创建
    local attr = lfs.attributes(dirPath)
    if not attr then
        -- 逐级创建目录
        local pluginsDir = FileUtil:getMapPath() .. "plugins/"
        local pluginsAttr = lfs.attributes(pluginsDir)
        if not pluginsAttr then
            local success, err = lfs.mkdir(pluginsDir)
            if not success then
                print("failed to create plugins directory: " .. (err or "unknown error"))
                return
            end
        end
        
        local success, err = lfs.mkdir(dirPath)
        if not success then
            print("failed to create shop directory: " .. (err or "unknown error"))
            return
        end
        print("created directory: " .. dirPath)
    end
    
    -- 转换为JSON字符串
    local jsonData = json.encode(shopData)
    
    -- 尝试写入文件 (使用io.open方式，如果支持的话)
    local file = io.open(fullPath, "w")
    if file then
        file:write(jsonData)
        file:close()
        print("save shops to file: " .. fullPath)
    else
        print("failed to create shops file: " .. fullPath)
    end
end

-- 从JSON文件加载商店数据
function SShopMgr:loadShopsFromFile()
    local fullPath = FileUtil:getMapPath() .. SHOP_DATA_PATH
    
    -- 检查文件是否存在
    if not PathUtil:isFileExist(fullPath) then
        print("shops file not exist: " .. fullPath)
        return
    end
    
    -- 尝试读取文件
    local file = io.open(fullPath, "r")
    if not file then
        print("failed to read shops file: " .. fullPath)
        return
    end
    
    local jsonData = file:read("*all")
    file:close()
    
    if not jsonData or jsonData == "" then
        print("shops file is empty")
        return
    end
    
    -- 解析JSON数据
    local success, shopData = pcall(json.decode, jsonData)
    if not success or not shopData then
        print("shops file format error")
        return
    end
    
    -- 清空现有商店数据
    Shops = {}
    
    -- 恢复index
    if shopData.index then
        index = shopData.index
    end
    
    -- 恢复商店数据
    if shopData.shops then
        for id, saveInfo in pairs(shopData.shops) do
            local shop = Shop.new(id, saveInfo)
            if shop then
                Shops[id] = shop
            end
        end
    end
    
    local shopCount = TableUtil.getTableSize(Shops)
    print("load " .. shopCount .. " shops from file")
    
    -- 同步到所有客户端
    if shopCount > 0 then
        local syncData = {}
        for id, shop in pairs(Shops) do
            syncData[id] = shop:getSyncInfo()
        end
        PacketSender:broadCastPidPacket({
            pid = "syncShop",
            data = syncData
        })
        print("sync shops to all clients")
    end
end

-- 初始化商店管理器
function SShopMgr:init()
    self:loadShopsFromFile()
end

function SShopMgr:addShop(data)
    local syncData = {}
    for _, info in pairs(data) do
        if TableUtil.getTableSize(Shops) >= Define.ShopMax then
            return
        end
        local shop = Shop.new(index, info)
        if shop then
            Shops[tostring(index)] = shop
            syncData[tostring(index)] = shop:getSyncInfo()
            index = index + 1
        end
    end
    PacketSender:broadCastPidPacket({
        pid = "syncShop",
        data = syncData
    })
    -- 保存到文件
    self:saveShopsToFile()
end

function SShopMgr:createNewShop(userId, pos, yaw)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    if TableUtil.getTableSize(Shops) >= Define.ShopMax then
        PidPacketSender:sendShopTip(player.userId, "gui.shop.npc.max")
        return false
    end
    local syncData = {}
    local shopId = tostring(index)
    local shop = Shop.new(shopId, {
        goods = {},
        pos = pos,
        yaw = yaw
    })
    if shop then
        Shops[shopId] = shop
        syncData[shopId] = shop:getSyncInfo()
        PacketSender:broadCastPidPacket({
            pid = "syncShop",
            data = syncData
        })
        index = index + 1
        -- 保存到文件
        self:saveShopsToFile()
        return shopId
    end
    return false
end

function SShopMgr:removeShop(id)
    local shop = Shops[tostring(id)]
    if not shop then
        return
    end
    shop:onRemove()
    Shops[tostring(id)] = nil
    PacketSender:broadCastPidPacket({
        pid = "removeShop",
        id = id
    })
    -- 保存到文件
    self:saveShopsToFile()
end

function SShopMgr:syncShop(userId)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    local data = {}
    for id, shop in pairs(Shops) do
        data[id] = shop:getSyncInfo()
    end
    player:sendPacket({
        pid = "syncShop",
        data = data
    })
end

---@return SShop
function SShopMgr:getShop(id)
    return Shops[tostring(id)]
end

function SShopMgr:tryPlaceShopNpc(userId, pos, yaw)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    local customGame = T(Global, "customGame")
    if not customGame:checkOwner(userId) and player:getPermissionRole() ~= Define.CustomGamePermissionRole.Admin then
        PidPacketSender:sendShopTip(player.userId, "gui.shop.no.permission")
        return
    end
    if player:haveItemCount(Define.NpcItemId) <= 0 then
        PidPacketSender:sendShopTip(player.userId, "gui.shop.no.enough.item")
        return
    end
    if TableUtil.getTableSize(Shops) >= Define.ShopMax then
        PidPacketSender:sendShopTip(player.userId, "gui.shop.npc.max")
        return
    end
    local shopId = self:createNewShop(userId, pos, yaw)
    if shopId then
        player:removeItem(Define.NpcItemId, 1)
    end
end
SShopMgr:init()
return SShopMgr